import{z as s,x as B,o as e,c as p,q as E,j as o,D as i,d as l,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"金属与 via 协同","description":"","frontmatter":{"title":"金属与 via 协同","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/metal-via-co-optimization.md","filePath":"litho/metal-via-co-optimization.md","lastUpdated":1791413859000}'),A={name:"litho/metal-via-co-optimization.md"};function v(d,a,D,c,m,h){const t=B("Mermaid");return e(),p("div",null,[a[2]||(a[2]=E('<h1 id="金属与-via-协同" tabindex="-1">金属与 via 协同 <a class="header-anchor" href="#金属与-via-协同" aria-label="Permalink to &quot;金属与 via 协同&quot;">​</a></h1><div class="epigraph"><p>via 不是贴在金属上的独立孔；覆盖、着色和套刻把上下金属与通孔收成同一张可印网格，分家优化会把电学开路写进 LRC 绿灯。</p><footer>—— 对照互连 DTCO、via coverage 与多重图形着色的公开讨论</footer></div><p><a href="/litho/sram-cell-patterning">上一课</a>把 SRAM 收成独立合同。缺口是互连：金属线宽、via 尺寸、enclosure 与颜色必须一起选，否则覆盖规则与 tip 规则互相打架。本课钉金属–via 协同，并结束「仿真、模型与验证」门。胶形如何变成硅与介质里的槽和孔，交给下一课程第一课<a href="/litho/plasma-basics">等离子体基础</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>via 覆盖（enclosure）来自套刻加 CD：下层金属太窄或 via 太大，位移后 via 落在介质上，开路或高阻。<a href="/litho/overlay-budget">套刻预算</a> 已分解数字；本课问网格：via 是否落在金属中心网格、是否自对准、是否允许 via 跨 jog。多重图形下，via 色与上下金属色的约束构成三维冲突——不是单层冲突图能看完。</p><p>缺口是<strong>协同网格</strong>，不是再讲一次接触孔成像。金属层 LFD 若不管 via，布线器会画出「金属可印、via 无法覆盖」的合法 DRC。反向亦然：via 先冻尺寸，金属再收 tip，密度在交界处死。</p>',6)),(e(),o(n,null,{default:i(()=>[r(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOM%5B%22via%20%E5%90%8D%E4%B9%89%E5%B1%85%E4%B8%AD%E5%9C%A8%E9%87%91%E5%B1%9E%E4%B8%8A%22%5D%20--%3E%20OVL%5B%22%E5%A5%97%E5%88%BB%E5%81%8F%E7%A7%BB%22%5D%0A%20%20NOM%20--%3E%20CDU%5B%22%E7%BA%BF%E5%AE%BD%E4%B8%8E%E5%AD%94%E5%BE%84%E6%B6%A8%E8%90%BD%22%5D%0A%20%20OVL%20--%3E%20LEFT%5B%22%E5%89%A9%E4%BD%99%E8%A6%86%E7%9B%96%20%3D%20(%E9%87%91%E5%B1%9E%E5%AE%BD-%E5%AD%94%E5%BE%84)%2F2%20-%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20CDU%20--%3E%20LEFT%0A%20%20JOG%5B%22%E9%87%91%E5%B1%9E%20jog%3A%20via%20%E8%90%BD%E5%88%B0%E7%BA%BF%E7%AB%AF%22%5D%20--%3E%20LEFT%0A%20%20LEFT%20--%3E%20Q%7B%22%E8%A6%86%E7%9B%96%E4%BB%8D%E5%A4%A7%E4%BA%8E%E9%9B%B6%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20GOOD%5B%22%E8%BF%9E%E9%80%9A%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20BAD%5B%22%E5%BC%80%E8%B7%AF%E6%88%96%E9%AB%98%E9%98%BB%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">enclosure（包覆量）翻译成算术：金属线宽 40 nm、孔径 30 nm，理想居中时四周各剩 5 nm 余量；套刻一偏 6 nm，孔边就探出金属外——开路。这就是&quot;覆盖是套刻和 CD 共同吃掉的余量&quot;的意思，也是它必须联立预算的原因。</span></p><h3 id="自对准-via-换的是掩模还是工艺" tabindex="-1">自对准 via 换的是掩模还是工艺 <a class="header-anchor" href="#自对准-via-换的是掩模还是工艺" aria-label="Permalink to &quot;自对准 via 换的是掩模还是工艺&quot;">​</a></h3><p>自对准通孔用介质或硬掩模把 via 锁到金属槽，套刻项下降，换来切线或填槽的刻蚀难度。这是助推器逻辑在 BEOL 的版本。不能自对准时，覆盖规则直接吃 overlay 与 CDU，金属不能再按纯光学最小宽度设计。</p><p><span class="marginnote">最终判据是电学连通与可靠性（电迁徙、介质击穿），不是 via 顶视圆。LRC 覆盖检查是代理，TEM 抽样才看见剖面偏离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>联合变量：金属节距与取向、via 网格、分解色、enclosure、是否自对准。评估：覆盖 PV（含套刻角）、via 打开随机窗、金属 tip 与 via 落点冲突、着色三维约束。输出：一套互连设计规则 + OPC 保持集（含 via-metal clips）。与 <a href="/litho/edge-placement-error">EPE</a> 衔接：via 相对金属边的 EPE 是本课的签核量，不是再定义 EPE。</p><p>仿真账单：via 层与金属层必须同版本核，分开校准会在覆盖上出现假绿。</p><p>保持集要含：网格对齐 via、线端 via、jog 旁 via、SRAM 局部互连。只校准密线中心 via，LRC 会在时钟网格和标准单元销钉上假绿。BEOL DTCO 把覆盖写成 EPE 的几何化，本课要求校准 clips 覆盖这些 EPE 角。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>覆盖余量 \\(\\approx\\) (金属宽度 − via 宽度)/2 − overlay − CDU 组合。网格对齐使平均 enclosure 最大；jog 让 via 落到线端，enclosure 被 tip 缩短吃掉——于是 tip 规则与 via 规则必须联立。着色：via 不能同时与「错误色」的上下金属冲突。协同失败的典型症状是逻辑 LRC 绿、SRAM 或时钟网格红，或电学 via 链良率差而 CD 报表好看。</p><p><span class="marginnote">着色可以想成排班表：多重图形把每层金属和 via 分到不同的掩模&quot;班次&quot;，via 的班次不能与上下金属的错误班次同时冲突。单看一层排班永远合法，三层联看才发现有人被排了两个班——这就是着色冲突要三维联立求解的原因。</span></p><p><span class="marginnote">常见误区是看到 LRC 全绿就认为 via 高枕无忧。LRC 查的是顶视几何这个代理，真正的开路常藏在剖面里：刻蚀偏斜、填孔空洞、线端缩短，要靠电学 via 链和 TEM 抽样才能抓到。</span></p>',12)),(e(),o(n,null,{default:i(()=>[r(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E9%87%91%E5%B1%9E%E7%BD%91%E6%A0%BC%20%2F%20%E8%89%B2%22%5D%20--%3E%20VIA%5B%22via%20%E7%BD%91%E6%A0%BC%20%2F%20%E8%89%B2%22%5D%0A%20%20VIA%20--%3E%20ENC%5B%22enclosure%20%2B%20%E5%A5%97%E5%88%BB%E8%A7%92%22%5D%0A%20%20M%20--%3E%20ENC%0A%20%20ENC%20--%3E%20ELEC%5B%22%E8%BF%9E%E9%80%9A%E4%B8%8E%E5%8F%AF%E9%9D%A0%E6%80%A7%22%5D%0A%20%20SA%5B%22%E8%87%AA%E5%AF%B9%E5%87%86%E9%80%89%E9%A1%B9%22%5D%20--%3E%20ENC%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写等离子体化学，只声明转印将改 enclosure 的 AEI 值。不发明某节点 via 尺寸表。全芯片仿真仍用紧凑核；via 三维剖面抽检用 3D 胶/刻蚀，不进 OPC 内循环。</p><p>后课默认：互连规则是金属–via 联立合同。下一课程从等离子体把胶浮雕变成槽与孔的物理开始，校准过的刻蚀核将在那里找到腔体对应物。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>金属与 via 必须同一网格、同版本核、联立 enclosure。</li><li>自对准用工艺难度换套刻余量。</li><li>jog 与 tip 是覆盖的隐形杀手。</li><li>出处：BEOL DTCO 与 via coverage 公开讨论；EPE 与套刻预算的几何化。</li></ul>',5))])}const _=s(A,[["render",v]]);export{u as __pageData,_ as default};
